-- DROP FUNCTION public.date_to_yearweek(timestamp);

CREATE OR REPLACE FUNCTION public.date_to_yearweek(some_time timestamp without time zone)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
    SELECT (EXTRACT(ISOYEAR FROM some_time AT TIME ZONE 'UTC')::integer * 100) +
           (EXTRACT(WEEK FROM (some_time AT TIME ZONE 'UTC' + INTERVAL '0 HOURS'))::integer)
$function$
;

-- Permissions

ALTER FUNCTION public.date_to_yearweek(timestamp) OWNER TO postgres;
GRANT ALL ON FUNCTION public.date_to_yearweek(timestamp) TO postgres;

-- DROP FUNCTION public.update_cash_cache();

CREATE OR REPLACE FUNCTION public.update_cash_cache()
 RETURNS void
 LANGUAGE plpgsql
AS $function$

DECLARE
  dbsetting integer;
  playerdata cash_cache%ROWTYPE;

BEGIN
