-- DROP FUNCTION public.update_cash_cache_date(int4, _int4);

CREATE OR REPLACE FUNCTION public.update_cash_cache_date(integer, integer[])
 RETURNS void
 LANGUAGE plpgsql
AS $function$

DECLARE
  playerdata cash_cache%ROWTYPE;

BEGIN
